def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        edge_id = i + 1
        edges.append((u, v, w, edge_id))
        adj[u].append((v, w, edge_id))
        adj[v].append((u, w, edge_id))

    def can_reach(start, end, blocked):
        visited = [False] * (n + 1)
        visited[start] = True
        queue = [start]
        idx = 0
        while idx < len(queue):
            curr = queue[idx]
            idx += 1
            if curr == end:
                return True
            for neighbor, _, edge_id in adj[curr]:
                if not visited[neighbor] and edge_id not in blocked:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return False

    # Check if already disconnected (0 edges)
    if not can_reach(s, t, set()):
        return "0\n0\n"

    # Try removing 1 edge
    best_single = float('inf')
    best_edge = -1

    for u, v, w, edge_id in edges:
        blocked = {edge_id}
        if not can_reach(s, t, blocked):
            if w < best_single:
                best_single = w
                best_edge = edge_id

    if best_single != float('inf'):
        return f"{best_single}\n1\n{best_edge}"

    # Try removing 2 edges
    best_pair = float('inf')
    best_edges_pair = []

    # Strategy 1: edges incident to s and t
    s_edges = []
    t_edges = []

    for u, v, w, edge_id in edges:
        if u == s or v == s:
            s_edges.append((u, v, w, edge_id))
        if u == t or v == t:
            t_edges.append((u, v, w, edge_id))

    for e1 in s_edges:
        for e2 in t_edges:
            if e1[3] != e2[3]:  # Different edges
                blocked = {e1[3], e2[3]}
                if not can_reach(s, t, blocked):
                    cost = e1[2] + e2[2]
                    if cost < best_pair:
                        best_pair = cost
                        best_edges_pair = [e1[3], e2[3]]

    # Strategy 2: all pairs (if not already found)
    found = False
    if best_pair == float('inf'):
        for i in range(m):
            for j in range(i + 1, m):
                e1_id = edges[i][3]
                e2_id = edges[j][3]
                if e1_id != e2_id:
                    blocked = {e1_id, e2_id}
                    if not can_reach(s, t, blocked):
                        cost = edges[i][2] + edges[j][2]
                        if cost < best_pair:
                            best_pair = cost
                            best_edges_pair = [e1_id, e2_id]
                            found = True

    if best_pair != float('inf'):
        return f"{best_pair}\n2\n{best_edges_pair[0]} {best_edges_pair[1]}"

    return "-1"

