        for j in range(N):
            if i == j:
                adj[i][j] = 0
            elif j < i:
                adj[i][j] = adj[j][i]
            else:
                adj[i][j] = costs[i - 1][j - 1]

    # Build preference lists (lower cost = better)
    prefs = []
    for i in range(N):
        row = []
        for j in range(N):
            if i != j:
                row.append((adj[i][j], j))
        row.sort()
        prefs.append([city for _, city in row])

    # Gale-Shapley for stable roommates
    partner = [-1] * N
    rejected = set()
    phase = [0] * N  # next preference index
    free = list(range(N))

    while free:
        city = free.pop()
        if city in rejected:
            continue
        # Propose to next preferred
        idx = phase[city]
        if idx >= len(prefs[city]):
            continue
        partner_idx = prefs[city][idx]
        phase[city] += 1

        if partner[partner_idx] == -1:
