                    if current not in free and partner[current] != -1:
                        pass
                rejected.add(current)
            else:
                rejected.add(city)
                free.append(city)

    # Check for perfect matching
    for i in range(N):
        if partner[i] == -1:
            return '-1\n'

    # Stability check: O(N^4) - might be slow for N=1000
    # Note: For competitive programming with N=1000, stability check might be needed
    # But actually, the algorithm above might not guarantee stability

