        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        operations.append((t, x_prime, y))

    # earliest_time[v] = earliest step to reach exactly v bananas (1-indexed)
    earliest_time = [-1] * (m + 1)

    # current contains all reachable banana counts
    current = {0}

    for step in range(1, n + 1):
        t, x_prime, y = operations[step - 1]

        next_set = set()

        if t == 1:
            # Type 1: k := ceil(k + x)
            # Check if x is integer
            if x_prime % 100000 == 0:
                x = x_prime // 100000  # Integer
                # Each application adds x, so a applications add a*x
                for k in current:
                    if k <= m:
                        for a in range(y + 1):
                            val = k + a * x
                            if 0 <= val <= m:
                                next_set.add(val)
            else:
                # x is fractional
                floor_x = x_prime // 100000
                # ceil(k + x) = k + floor(x) + 1 when x >= 1 and x is not integer
                # After a iterations: k + a * (floor(x) + 1)
                increment = floor_x + 1
                for k in current:
                    if k <= m:
                        for a in range(y + 1):
                            val = k + a * increment
                            if 0 <= val <= m:
                                next_set.add(val)
        else:
            # Type 2: k := ceil(k * x), applied a times
            if x_prime % 100000 == 0:
                x = x_prime // 100000  # Integer
            else:
                x = x_prime / 100000.0  # Float

            if x < 0:
                continue  # Invalid x based on constraints

            for k in current:
                if k <= m:
                    # For each a from 0 to y, apply the operation a times
                    for a in range(y + 1):
                        if a == 0:
                            val = k
                        else:
                            val = k
                            for _ in range(a):
                                if k == 0:
                                    break
                                if x_int := x_prime / 100000.0:
                                    # Use repeated ceiling
                                    val = math.ceil(val * x_int)
                        if 0 <= val <= m:
                            next_set.add(val)

        # Update earliest times for values in this step
        for val in next_set:
            if earliest_time[val] == -1:
                earliest_time[val] = step

        current = next_set

    # Output results for j=1 to m
    result = [str(earliest_time[j]) for j in range(1, m + 1)]
    return ' '.join(result) + '\n'

