    dedup_ids = list(set(non_empty_ids))
    num_friends = len(dedup_ids)

    if num_friends == 0:
        return '0'

    friends_ids = sorted(dedup_ids)
    name_to_global = {}
    for glob_id, friend_id in enumerate(friends_ids):
        best_name = id_to_name[friend_id]
        name_to_global[best_name] = glob_id

    # Build conflict graph (adjacency list)
    conflicts = [0] * num_friends  # bitmask of conflicting friends

    for iv in intervals:
        iv_set = set()
        for name in iv:
            gid = name_to_global[name]
            if gid != -1:
                iv_set.add(gid)
        if len(iv_set) > 0:
            for i in iv_set:
                for j in iv_set:
                    if i < j:
                        conflicts[i] |= (1 << j)
                        conflicts[j] |= (1 << i)

    # Meet-in-the-middle for maximum independent set
    half = num_friends // 2

    def enumerate_half(ids_list, start_offset, conflicts, n_total):
        results = []
        n = len(ids_list)

        for mask in range(1 << n):
            # Check if this subset of this half is an independent set
            is_indep = True
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                for j in range(i + 1, n):
                    if not (mask & (1 << j)):
                        continue
                    # Check if friends from different parts of this half conflict
                    if (conflicts[ids_list[i] + start_offset] >> (ids_list[j] + start_offset)) & 1:
                        is_indep = False
                        break
                if not is_indep:
                    break

            if is_indep:
                # Count size and build conflict mask for other half
                cnt = bin(mask).count('1')
                conf_mask = 0
                for i in range(n):
                    if mask & (1 << i):
                        friend_idx = ids_list[i]
                        c = conflicts[friend_idx + start_offset]
                        # Mark conflicting friends - shift to global positions
                        for bit in range(n_total):
                            if (c >> bit) & 1 and bit + start_offset >= start_offset + n:
                                global_idx = bit + start_offset
                                diff = global_idx - (start_offset + n)
                                if diff < n:
                                    conf_mask |= (1 << diff)
                results.append((mask, cnt, conf_mask))

        return results

    result = 0

    # Try both split points
    for split_point in [half, half]:
        # Try both directions
        direction = 0  # 0 = first half is left, 1 = first half is right

        if direction == 0:
            h1_ids = friends_ids[:split_point]
            h1_start = 0
            h2_ids = friends_ids[split_point:]
            h2_start = split_point
        else:
            h1_ids = friends_ids[split_point:]
            h1_start = split_point
            h2_ids = friends_ids[:split_point]
            h2_start = 0

        # Actually simplify: always process first half then second half
        first_half = friends_ids[:half]
        second_half = friends_ids[half:]

        if first_half:
            iso1 = enumerate_half(first_half, 0, conflicts, num_friends)
        else:
            iso1 = []

        if second_half:
            iso2 = enumerate_half(second_half, half, conflicts, num_friends)
        else:
            iso2 = []

        # Track maximum
        for m1, cnt1, masked in iso1:
            for m2, cnt2, _ in iso2:
                # Check compatibility: combined must be independent
                s1_set = set(first_half[i] for i in range(len(first_half)) if m1 & (1 << i))
                s2_set = set(second_half[i] for i in range(len(second_half)) if m2 & (1 << i))
                combined = s1_set | s2_set
                valid = True
                for f1 in combined:
                    for f2 in combined:
                        if f1 < f2 and (conflicts[f1] >> f2) & 1:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    result = max(result, cnt1 + cnt2)

        # For compatibility we don't need directional consideration
        break

    return str(result)

