    # Helper: check if a prefix can lead to a valid solution
    def can_complete(prefix):
        """
        Check if prefix can be completed to a valid word.
        Returns True if possible, False if impossible.
        """
        # Check if prefix itself violates any rule
        for pos1, t1, pos2, t2 in actual_rules:
            if pos1 - 1 < len(prefix) and char_type[prefix[pos1 - 1]] == t1:
                if pos2 - 1 < len(prefix):
                    # Both positions are in prefix
                    if char_type[prefix[pos2 - 1]] != t2:
                        return False
                else:
                    # pos1 in prefix, pos2 in suffix - can be satisfied
                    pass
        return True

    # Try to find the answer
    def find_word(pos, current):
        """Backtracking to find smallest valid word >= s."""
        if current > s:
            # Already greater than s, just fill remaining positions with smallest valid
            for i in range(pos, n):
                for c_idx in range(l):
                    c = chr(ord('a') + c_idx)
