            if is_valid(current):
                return current
            return None

        # Try to keep prefix and find smallest valid character >= s[pos]
        start_char = ord(s[pos]) if pos < len(s) and current[:pos] == s[:pos] else ord('a')

        for c_idx in range(l):
            c = chr(ord('a') + c_idx)
            # If we need word >= s, char must be at least s[pos]
            if ord(c) < start_char:
