    # Try different prefixes
    best = None

    def dfs(pos, current):
        nonlocal best

        # If we already found a result better than s, and best is found
        if best and current[0:len(best[:pos+1])] > best[:pos+1]:
            return

        if pos == n:
            if is_valid(current):
                if best is None or current < best:
