import math

def compute_circumcenter(p1, p2, p3):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3

    d = 2.0 * (x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2))
    if abs(d) < 1e-15:
        return None

    ux = ((x1**2 + y1**2)*(y2 - y3) + (x2**2 + y2**2)*(y3 - y1) + (x3**2 + y3**2)*(y1 - y2)) / d
    uy = ((x1**2 + y1**2)*(x3 - x2) + (x2**2 + y2**2)*(x1 - x3) + (x3**2 + y3**2)*(x2 - x1)) / d

    return (ux, uy)

def solution(data):
    lines = data.strip().split('\n')
    if not lines or not lines[0]:
        return '-1'

    try:
        n = int(lines[0])
    except:
        return '-1'

    centers = []
    for i in range(1, n + 1):
        if i >= len(lines):
            break
        parts = lines[i].strip().split()
        if len(parts) >= 2:
            try:
                centers.append((float(parts[0]), float(parts[1])))
            except:
                pass

    if len(centers) < 3:
        return '-1'

    max_time = -1
    found = False

    def dist(p1, p2):
        return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

    for i in range(len(centers)):
        for j in range(i + 1, len(centers)):
            for k in range(j + 1, len(centers)):
                d1 = dist(centers[i], centers[j])
                d2 = dist(centers[j], centers[k])
                d3 = dist(centers[i], centers[k])

                if d1 < 1e-9 or d2 < 1e-9 or d3 < 1e-9:
                    continue
                if abs(d1 - d2) < 1e-9 or abs(d2 - d3) < 1e-9 or abs(d3 - d1) < 1e-9:
                    continue
                if abs(d1 + d2 - d3) < 1e-9 or abs(d2 + d3 - d1) < 1e-9 or abs(d3 + d1 - d2) < 1e-9:
                    continue

                circ = compute_circumcenter(centers[i], centers[j], centers[k])
                if circ is None:
                    continue

                ux, uy = circ
                for t in range(len(centers)):
                    dist_to_center = math.sqrt((ux - centers[t][0])**2 + (uy - centers[t][1])**2)
                    t_val = max(dist_to_center / 2, max_time)
                    max_time = t_val
                    found = True

    return f'{max_time:.6f}\n' if found else '-1'

MOD = 10**9 + 7

def pow_mod(a, b, m):
    """Compute a^b mod m using binary exponentiation"""
    res = 1
    a %= m
    while b > 0:
        if b & 1:
            res = (res * a) % m
        a = (a * a) % m
        b >>= 1
    return res

def concat_range(a, b):
    """Concatenate all integers from a to b as strings, return (value mod MOD, length)"""
    if a > b:
        return 0, 0

    result = 0
    total_len = 0

    num = a
    while num <= b:
        length = len(str(num))
        start = num
        end = min(b, 10**length - 1)

        if length == 1:
            # Single digit numbers: just concatenate
            for _ in range(start, end + 1):
                result = (result * 10) % MOD
                result = (result + ()) % MOD if _ != start else (result + _ * 10) % MOD
            total_len += end - start + 1
        else:
            # Multi-digit: multiply previous result by 10^(this length) first
            shift = pow_mod(10, length, MOD)
            for _ in range(start, end + 1):
                result = (result * shift) % MOD
                result = (result + _) % MOD
                total_len += 1

    return result, total_len

def concat_len_calc(a, b):
    """Calculate total length of concatenating a to b"""
    if a > b:
        return 0

    total = 0
    num = a
    while num <= b:
        length = len(str(num))
        start = num
        end = min(b, 10**length - 1)
        total += end - start + 1
        num = end + 1
    return total

def repeat_expand(val, k, length, mod):
    """Expand repeated concatenation of val (where val has 'length' digits) k times"""
    if k == 1:
        return val

    r = pow_mod(10, length, mod)
    rk = pow_mod(r, k, mod)

    numerator = (rk - 1 + mod) % mod
    denominator = (r - 1 + mod) % mod

    # Modular inverse using Fermat's Little Theorem
    inv_denom = pow_mod(denominator, mod - 2, mod)

    result = (val * numerator) % mod
    result = (result * inv_denom) % mod

    return result, k * length

