def solution(m):
    n = len(m)

    # If empty or all empty, no profile needed
    if n == 0 or all(c == '_' for c in m):
        return '\n0\n'

    # Convert mask to boolean (True = forced/filled, False = empty)
    target_mask = [c == '#' for c in m]

    # Check every possible profile (each profile is a sequence of block lengths)
    # Since we need ANY profile that works, try profiles with sum from n down to 1
    for total_slots in range(n + 1, 0, -1):
        # Generate all ways to partition total_slots into blocks
        # Start from larger number of blocks and work down
        k = min(total_slots, 100001)
        m_idx = total_slots // k if k > 0 else 1

        for blocks in range(1, k + 1):
            # Blocks must be at minimum 1
            if blocks * m_idx > total_slots and blocks > 1:
                continue

            # Profile with blocks blocks of length m_idx
            profile = [m_idx] * blocks
            if total_slots != sum(profile):
                continue

            # Adjust last block if needed
            if total_slots > sum(profile):
                profile[-1] += total_slots - sum(profile)

            # Check if this profile generates the target mask
            forced = []
            # Generate valid placements for this profile
            valid_placements = []

            def backtrack(idx, current_placements, pos):
                if idx == k:
                    valid_placements.append(current_placements)
                    return
                start = sum(current_placements) + idx
                remaining = profile[idx+1:] if idx < k - 1 else []
                remaining_sum = sum(remaining) if remaining else 0
                min_gaps = (k - idx - 1) if idx < k - 1 else 0

                for p in range(start, n - remaining_sum - min_gaps):
                    if p + profile[idx] > n:
                        break
                    current_placements.append(p)
                    backtrack(idx + 1, current_placements, p + profile[idx] + 2)
                    current_placements.pop()

            backtrack(0, [], 0)

            if not valid_placements:
                continue

            # Compute forced mask: cells filled in ALL placements
            covered = [False] * n
            for placement in valid_placements:
                for idx, pos in enumerate(placement):
                    if idx < len(profile):
                        for j in range(profile[idx]):
                            if pos + j < n:
                                covered[pos + j] = True

            # Check if this matches target
            matches = True
            for i in range(n):
                if covered[i] != target_mask[i]:
                    matches = False
                    break

            if matches:
                return str(blocks) + '\n' + ' '.join(map(str, profile))

    return '-1\n'


