    for k in range(1, min(n, 100) + 1):
        # Try each partition of n
        for prod in partition(n, k, []):
            # prod is a list of block sizes
            profile = prod

            # Generate all valid placements
            placements = get_valid_placements(n, profile)
            if not placements:
                continue

            # Compute forced mask
            forced = compute_forced_mask(n, profile, placements)

            if forced == target:
                return str(k) + '\n' + ' '.join(map(str, profile))

    return '-1\n'


def partition(n, k, existing=None):
    if existing is None:
        existing = []
    if k == 1:
        if n == 0:
            yield []
        else:
            yield [n]
    else:
        for i in range(1, n - (k - 1) + 1):
            for p in partition(n - i, k - 1, existing + [i]):
                yield p


def get_valid_placements(n, profile):
    """Get all valid placements of blocks on board of length n"""
    k = len(profile)
    placements = []

    if k == 0:
        return [[]]

    def backtrack(idx, current_start):
        if idx == k - 1:
            placements.append(list(current_start))
            return

        for start in range(current_start, n - sum(profile[idx+1:])):
            end = start + profile[idx] + 1  # +1 for at least 1 gap
            if end > len(profile):
                continue
            current_start.append(start)
            backtrack(idx + 1, end)
            current_start.pop()

    backtrack(0, 0)
    return placements


def compute_forced_mask(n, profile, placements):
    """Compute which cells are forced (filled in all placements)"""
    forced = []
    for i in range(n):
        is_forced = True
        for ind in placements:
            if not covered_in_placement(i, ind, profile):
                is_forced = False
                break
        if is_forced and i not in forced:
            forced.append(i)
    return forced


def covered_in_placement(cell, placement, profile):
    """Check if cell is covered by the current placement"""
    for pos, length in zip(placement, profile):
        if pos <= cell < pos + length:
            return True
    return False

