def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines[0].strip():
        return '0'

    n, m = map(int, lines[0].split())

    # If no constraints, all 2^n strings are valid
    if m == 0:
        return str(1 << n)

    # Parse constraints
    constraints = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        s_bits = parts[0]
        c = int(parts[1])
        # Convert binary string to bitmask
        # Position j (0-indexed from left) maps to bit j
        mask = 0
        for j in range(n):
            if s_bits[j] == '1':
                mask |= (1 << j)
        constraints.append((mask, c))

    count = 0

    # Helper to count bits without bit_count() for Python 3.8 compatibility
    def bit_count(x):
        c = 0
        y = x
        while y:
            y &= y - 1
            c += 1
        return c

    def dfs(pos, current_matches):
        nonlocal count

        if pos == n:
            # Check if all constraints are satisfied exactly
            for mask, c in constraints:
                if bit_count(current_matches & mask) != c:
                    return
            count += 1
            return

        # Try placing 0 or 1 at each position
        for bit in [0, 1]:
            new_matches = current_matches | (bit << pos)

            # Pruning: check if placing this bit violates any constraint
            possible = True
            for mask, c in constraints:
                matches = bit_count(new_matches & mask)
                if matches > c:
                    possible = False
                    break

            if possible:
                dfs(pos + 1, new_matches)

    dfs(0, 0)
    return str(count)


