def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Each frog: (position, jump_length, original_index, is_alive)
    frogs = []
    for i in range(n):
        p, a = map(int, lines[i + 1].split())
        frogs.append({'position': p, 'jump': a, 'id': i + 1, 'alive': True})

    # Map from cell position to list of frog indices that are alive there
    occupied = {}
    for i in range(n):
        if frogs[i]['alive']:
            pos = frogs[i]['position']
            if pos not in occupied:
                occupied[pos] = []
            occupied[pos].append(i)

    current_frog = 0

    while True:
        # Move to next alive frog
        while current_frog < n and not frogs[current_frog]['alive']:
            current_frog += 1
        if current_frog >= n:
            break

        pos = frogs[current_frog]['position']
        jump = frogs[current_frog]['jump']

        if jump <= 0:
            frogs[current_frog]['alive'] = False
            current_frog += 1
            continue

        # Calculate destination
        dest = (pos + jump - 1) % m + 1

        # Get all cells on the path from pos (exclusive) to dest (inclusive)
        path_cells = []
        if dest >= pos:
            path_cells = list(range(pos + 1, dest + 1))
        else:
            path_cells = list(range(pos + 1, m + 1)) + list(range(1, dest + 1))

        # Count and remove frogs on the path
        knocked_idx = set()
        removed_idx = []

        for p in path_cells:
            if p in occupied:
                cell_frogs = occupied[p]
                for fidx in cell_frogs:
                    if fidx != current_frog and frogs[fidx]['alive']:
                        knocked_idx.add(fidx)

        # Remove knocked frogs from occupied lists
        for p in path_cells:
            if p in occupied:
                new_list = [fidx for fidx in occupied[p] if fidx not in knocked_idx]
                if new_list:
                    occupied[p] = new_list
                else:
                    del occupied[p]

        # Mark frogs as dead and update accusation_idx
        for fidx in knocked_idx:
            frogs[fidx]['alive'] = False

        # Update current frog's jump
        knocked_count = len(knocked_idx)
        frogs[current_frog]['jump'] = max(0, jump - knocked_count)

        # Move to next position (get next alive frog)
        current_frog += 1
        if current_frog >= n:
            current_frog = 0

    # Collect surviving frogs
    survivors = [frogs[i]['id'] for i in range(n) if frogs[i]['alive']]
    survivors.sort()

    result = f"{len(survivors)}\n{' '.join(map(str, survivors))}"
    return result

